"use client";

import React from "react";
import { cn } from "@/lib/utils";

export const GENIE_LOGO_BASE64 = "data:image/png;base64,";
export const GENIE_FULL_BASE64 = "data:image/png;base64,";

interface CoachGenieLogoProps {
  className?: string;
  variant?: "tight" | "full";
  size?: "sm" | "md" | "lg" | "xl" | "2xl";
  alt?: string;
  plain?: boolean;
}

export function CoachGenieLogo({
  className,
  variant = "tight",
  size = "md",
  alt = "CoachGenie Mascot",
  plain = false,
}: CoachGenieLogoProps) {
  const src = variant === "full" ? GENIE_FULL_BASE64 : GENIE_LOGO_BASE64;

  const plainSizeClasses = {
    sm: "h-7 w-7",
    md: "h-9 w-9",
    lg: "h-12 w-12",
    xl: "h-16 w-16",
    "2xl": "h-20 w-20",
  };


  const sizeClasses = {
    sm: "h-7 w-7 rounded-lg",
    md: "h-9 w-9 rounded-xl",
    lg: "h-12 w-12 rounded-2xl",
    xl: "h-16 w-16 rounded-2xl",
    "2xl": "h-20 w-20 rounded-3xl",
  };

  if (plain) {
    return (
      <img
        src={src}
        alt={alt}
        className={cn("shrink-0 object-contain drop-shadow-md select-none", plainSizeClasses[size], className)}
        loading="eager"
      />
    );
  }

  return (
    <div
      className={cn(
        "relative shrink-0 flex items-center justify-center overflow-hidden bg-gradient-to-br from-violet-600 to-indigo-600 border border-violet-400/30 shadow-md shadow-violet-500/20 select-none",
        sizeClasses[size],
        className
      )}
    >
      <img
        src={src}
        alt={alt}
        className="h-full w-full object-cover transform scale-110 drop-shadow-md"
        loading="eager"
      />
    </div>
  );
}
